/// <summary>
/// PaffH 28.02.25
/// </summary>
/// <param name = "_nDXBatchProcessingType">NDXBatchProcessingType</param>
/// <returns>records to change course of NDXBatchProcessingType</returns>
public int setBatchProcessingType(NDXBatchProcessingType _nDXBatchProcessingType)
{
    int counter = next setBatchProcessingType(_nDXBatchProcessingType);

    NDXBatchProcessingTable nDXBatchProcessingTable;
    NDXBatchProcessingTableProcess nDXBatchProcessingTableProcess;
    switch (_nDXBatchProcessingType)
    {
        case NDXBatchProcessingType::SalesCurrentYearRun2:
        case NDXBatchProcessingType::SalesLastYearRun2:
            ttsbegin;
            while select forupdate * from nDXBatchProcessingTable
                where nDXBatchProcessingTable.NDXBatchProcessingTableHeader == this.RecId
                && nDXBatchProcessingTable.BatchProcessingStatus != NDXBatchProcessingStatus::ToBeProcessed
                join nDXBatchProcessingTableProcess
                where nDXBatchProcessingTableProcess.RefRecId == nDXBatchProcessingTable.RecId
                && nDXBatchProcessingTableProcess.WithError == NoYes::Yes
            {
                nDXBatchProcessingTable.BatchProcessingStatus = NDXBatchProcessingStatus::ToBeProcessed;
                nDXBatchProcessingTable.BatchRetries += 1;
                nDXBatchProcessingTable.update();
                ++counter;
            }
            ttscommit;
            break;
    }
    return counter;
}
